/**
 * Yo!Kart auth helpers.
 *
 * Yo!Kart is a self-hosted platform. The App API does NOT use OAuth2.
 * Authentication uses an API key generated by the store administrator from
 * the Yo!Kart admin panel (Admin → Third Party API). The key is passed on
 * every request as the `api_key` query parameter.
 *
 * The adapter therefore:
 *  - Points `getAuthUrl` at the admin panel's API keys page (informational).
 *  - Throws from `exchangeCode` with clear instructions since the platform
 *    has no OAuth code-exchange flow.
 *
 * Credentials are passed to the adapter via `POST /v1/connections` with:
 *   { platform: 'yokart', credentials: { accessToken: '<api_key>', extra: { site: 'https://shop.example.com' } } }
 *
 * Docs: https://www.yo-kart.com/resource-center.html
 */

import type { Credentials } from '@opensteward/shared'

/**
 * Return the Yo!Kart admin panel URL where the operator can generate an
 * API key. This is informational only — it is not an OAuth authorization
 * endpoint.
 */
export function buildAuthUrl(site: string): string {
  return `${site.replace(/\/$/, '')}/admin/third-party-api`
}

export function exchangeCode(): Promise<Credentials> {
  throw new Error(
    'Yo!Kart does not use OAuth code exchange. ' +
      'Generate an API key in the Yo!Kart admin panel under Third Party API, ' +
      'then POST it to /v1/connections with body ' +
      '`{ platform: "yokart", credentials: { accessToken: "<api_key>", extra: { site: "https://shop.example.com" } } }`.',
  )
}
